-- Exact owner-approved three-question update. No answer, queue, schema or student-data writes.
-- Run with ROLLBACK for rehearsal; COMMIT only after exact-head release CI.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE ds_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE ds_job_before ON COMMIT DROP AS SELECT to_jsonb(c) AS row FROM public.ai_analysis_job_config c;
DO $guard$
BEGIN
  IF (SELECT count(*) FROM ds_before) <> 4800 THEN RAISE EXCEPTION 'corpus count drift'; END IF;
  IF (SELECT enabled FROM public.ai_analysis_job_config WHERE id=true) IS DISTINCT FROM false THEN RAISE EXCEPTION 'AI queue not paused'; END IF;
  IF (SELECT encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex') FROM public.questions q WHERE id='DS-104-1-22') IS DISTINCT FROM '8ee723d9745dcaf4ce022f4128a2da769df6456a334878c266445716fdb81481' THEN RAISE EXCEPTION 'preimage drift'; END IF;
  IF (SELECT encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex') FROM public.questions q WHERE id='DS-104-1-27') IS DISTINCT FROM '96618dbe2b33e5b503a54fd5942e4861724ace1dc933167c22aaad27a3a9348a' THEN RAISE EXCEPTION 'preimage drift'; END IF;
  IF (SELECT encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex') FROM public.questions q WHERE id='DS-104-1-29') IS DISTINCT FROM '11737869297bf2514dd203df2d66649849f913cc15bddc04cf03b460ca9f6352' THEN RAISE EXCEPTION 'preimage drift'; END IF;
  IF (SELECT encode(sha256(convert_to(pg_get_functiondef(t.tgfoid),'UTF8')),'hex') FROM pg_trigger t WHERE tgrelid='public.questions'::regclass AND tgname='trg_reset_ai_on_official_change') IS DISTINCT FROM '729a9c8e5158ebe73c65504ce988126d9e6de95d65eff8ed5bec9d6cacac74f0' THEN RAISE EXCEPTION 'reset trigger drift'; END IF;
END $guard$;
UPDATE public.questions SET question='團體工作紀錄可作為工作者檢視及評鑑團體運作的重要方式之一，下列有關團體紀錄的敘述何者錯誤？', opt_a='「摘要式紀錄」較能具體且深入的呈現團體過程與內容，適用於量化的評鑑，所花費的時間較多', opt_b='團體紀錄可以檢視團體目標達成狀態及成員參與狀態等重要面向，是團體成效評鑑工具之一', opt_c='紀錄裡的文字內容、相片等，須遵守保密原則及匿名處理', opt_d='任務性團體的紀錄，需在下次聚會前發給成員檢閱，並於下次會議開始前進行修正' WHERE id='DS-104-1-22';
UPDATE public.questions SET question='當女性社會工作人員與男性案主第二次在機構進行會談時，會談過程中，案主不斷稱讚社會工作人員，並對社會工作人員的建議言聽計從，此時該社會工作人員應該合理懷疑這是下面那一種專業關係的反應？', opt_a='反情感轉移', opt_b='情感轉移' WHERE id='DS-104-1-27';
UPDATE public.questions SET question='社會工作實務領域常運用「業務聯繫會報」與「個案研討會」等形式，由不同機構或不同專業的工作者，一起討論個案工作的方法。這種類型的會議，社會工作者需要面對的倫理議題為何？', opt_b='不同專業間的價值觀與介入焦點不一致', opt_c='不同機構間的代表權力分配的議題', opt_d='資訊分享程度與保密拿捏的問題' WHERE id='DS-104-1-29';
DO $assert$
BEGIN
  IF (SELECT to_jsonb(q) FROM public.questions q WHERE id='DS-104-1-22') IS DISTINCT FROM $expected${"id":"DS-104-1-22","law":null,"qno":"22","year":"104","major":null,"opt_a":"「摘要式紀錄」較能具體且深入的呈現團體過程與內容，適用於量化的評鑑，所花費的時間較多","opt_b":"團體紀錄可以檢視團體目標達成狀態及成員參與狀態等重要面向，是團體成效評鑑工具之一","opt_c":"紀錄裡的文字內容、相片等，須遵守保密原則及匿名處理","opt_d":"任務性團體的紀錄，需在下次聚會前發給成員檢閱，並於下次會議開始前進行修正","round":"第一次","topic":null,"answer":"A","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作直接服務","exp_trap":null,"keywords":null,"mnemonic":null,"question":"團體工作紀錄可作為工作者檢視及評鑑團體運作的重要方式之一，下列有關團體紀錄的敘述何者錯誤？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=110&code=104030&q=1&s=0602&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"pending","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"104030","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null}$expected$::jsonb THEN RAISE EXCEPTION 'unexpected postimage DS-104-1-22'; END IF;
  IF (SELECT to_jsonb(q) FROM public.questions q WHERE id='DS-104-1-27') IS DISTINCT FROM $expected${"id":"DS-104-1-27","law":null,"qno":"27","year":"104","major":null,"opt_a":"反情感轉移","opt_b":"情感轉移","opt_c":"反向作用","opt_d":"現實反應","round":"第一次","topic":null,"answer":"B","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作直接服務","exp_trap":null,"keywords":null,"mnemonic":null,"question":"當女性社會工作人員與男性案主第二次在機構進行會談時，會談過程中，案主不斷稱讚社會工作人員，並對社會工作人員的建議言聽計從，此時該社會工作人員應該合理懷疑這是下面那一種專業關係的反應？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=110&code=104030&q=1&s=0602&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"pending","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"104030","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null}$expected$::jsonb THEN RAISE EXCEPTION 'unexpected postimage DS-104-1-27'; END IF;
  IF (SELECT to_jsonb(q) FROM public.questions q WHERE id='DS-104-1-29') IS DISTINCT FROM $expected${"id":"DS-104-1-29","law":null,"qno":"29","year":"104","major":null,"opt_a":"個人價值與專業價值的衝突","opt_b":"不同專業間的價值觀與介入焦點不一致","opt_c":"不同機構間的代表權力分配的議題","opt_d":"資訊分享程度與保密拿捏的問題","round":"第一次","topic":null,"answer":"D","exp_raw":null,"exp_why":null,"mistake":null,"subject":"社會工作直接服務","exp_trap":null,"keywords":null,"mnemonic":null,"question":"社會工作實務領域常運用「業務聯繫會報」與「個案研討會」等形式，由不同機構或不同專業的工作者，一起討論個案工作的方法。這種類型的會議，社會工作者需要面對的倫理議題為何？","extension":null,"exp_others":null,"legal_note":null,"source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=110&code=104030&q=1&s=0602&t=Q","grading_mode":"standard","legal_status":"not_applicable","analysis_error":null,"analysis_status":"pending","accepted_answers":null,"legal_checked_at":null,"legal_source_url":null,"source_exam_code":"104030","analysis_attempts":0,"analysis_started_at":null,"analysis_completed_at":null,"legal_canonical_names":[],"analysis_last_attempt_at":null}$expected$::jsonb THEN RAISE EXCEPTION 'unexpected postimage DS-104-1-29'; END IF;
  IF EXISTS (SELECT 1 FROM ds_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN ('DS-104-1-22','DS-104-1-27','DS-104-1-29') AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated question changed'; END IF;
  IF EXISTS ((SELECT row FROM ds_job_before EXCEPT SELECT to_jsonb(c) FROM public.ai_analysis_job_config c) UNION ALL (SELECT to_jsonb(c) FROM public.ai_analysis_job_config c EXCEPT SELECT row FROM ds_job_before)) THEN RAISE EXCEPTION 'AI job changed'; END IF;
