SELECT id, opt_a, opt_b, opt_c, opt_d, answer, analysis_status, encode(sha256(convert_to(to_jsonb(q)::text,'UTF8')),'hex') AS postimage_sha256 FROM public.questions q WHERE id IN ('DS-104-1-22','DS-104-1-27','DS-104-1-29') ORDER BY id;
ROLLBACK;
